# -*- coding: utf-8 -*-
"""MANAPRINT — DUAL DAB 75 (maquette CANVA de Maeva).
NOUVELLE MAQUETTE de Maeva (24/11/2026, « dualdab_canva_12_A4 ») reprise TELLE QUELLE :
12 billets / feuille A4 PAYSAGE (3 colonnes x 4 rangées), traits de coupe en pointillés.
Le dessin du billet (cadre, « VOTRE JEU », capsules, ovales, soleil, rayons, éclairs,
pastille du N°) est rejoué TRAIT POUR TRAIT depuis la maquette (_DESSIN) ; on n'y pose
que les chiffres, le N° de série et les lettres.
Plages (inchangées), la lettre B I N G O sur chaque zone (24/11) :
   B  1-15 : les deux capsules du haut (le plus petit à gauche)
   I 16-30 : l'ovale du haut à droite   « a/b »
   N 31-45 : l'ovale du bas à gauche    « a/b »
   G 46-60 : les deux capsules du bas (le plus petit à gauche)
   O 61-75 : le soleil du centre
   -> 9 numéros différents par billet, crieur 1 à 75. Chiffres gras 26 · 27 · 30 pt comme la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, os as _os, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM = "Helvetica-Bold"

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0

# lettres : (lettre, x, y) de la pastille
PASTILLES = [("B", 88.16, 111.6), ("I", 185.7, 103.18), ("N", 49.2, 33.45),
             ("G", 224.22, 40.6), ("O", 155.9, 85.6)]


def _numeros(rng):
    b = sorted(rng.sample(range(1, 16), 2))
    i = sorted(rng.sample(range(16, 31), 2))
    n = sorted(rng.sample(range(31, 46), 2))
    g = sorted(rng.sample(range(46, 61), 2))
    o = rng.randint(61, 75)
    return b, i, n, g, o


def _txt(c, s, x, y, taille, col, police=POLICE_NUM, centre=True, esp=0):
    c.setFillColor(col)
    if esp:
        t = c.beginText(x, y); t.setFont(police, taille); t.setCharSpace(esp); t.setFillColor(col)
        t.textOut(s); t.setCharSpace(0); c.drawText(t)
    elif centre:
        c.setFont(police, taille); c.drawCentredString(x, y, s)
    else:
        c.setFont(police, taille); c.drawString(x, y, s)


def _billet(c, ox, oy, serie, nums, col):
    (b1, b2), (i1, i2), (n1, n2), (g1, g2), o = nums
    textes = [
        lambda: _txt(c, "VOTRE JEU", -30.92285, -3.401575, 9.5, NOIR, POLICE_NUM, esp=1),
        lambda: _txt(c, "DUAL DAB", 145.8938, 128.6929, 16.5, NOIR, "Helvetica", esp=1.6),
        lambda: _txt(c, str(b1), 62.36, 93.8731, 26, col),
        lambda: _txt(c, str(b2), 113.95, 93.8731, 26, col),
        lambda: _txt(c, "%d/%d" % (i1, i2), 226.2, 93.5151, 27, col),
        lambda: _txt(c, "%d/%d" % (n1, n2), 88.43, 23.78282, 27, col),
        lambda: _txt(c, str(g1), 197.86, 23.57389, 26, col),
        lambda: _txt(c, str(g2), 250.58, 23.57389, 26, col),
        lambda: _txt(c, str(o), 155.9, 55.59071, 30, col),
        lambda: _txt(c, "N\u00b0 %06d" % serie, 114.1841, 6.80315, 4.2, NOIR, centre=False),
        lambda: _txt(c, "89 52 98 83", 145.1339, 6.80315, 4.2, NOIR, centre=False),
    ]
    c.saveState()
    c.translate(ox, oy)
    c._code.append("q")
    for k, morceau in enumerate(_DESSIN):
        c._code.append(morceau)
        if k < len(textes):
            textes[k]()
    c._code.append("Q")
    for let, lx, ly in PASTILLES:
        c.setFillColor(colors.white); c.setStrokeColor(NOIR); c.setLineWidth(0.6)
        c.circle(lx, ly, 4.6, stroke=1, fill=1)
        c.setFillColor(col); c.setFont("Helvetica-Bold", 7.0); c.drawCentredString(lx, ly - 2.5, let)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 7575)
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in (1, 2):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in (1, 2, 3):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


